<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DormitoryOrderController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->canDo('dormitory.manage'),403);}
public function index(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('dormitory_order_drafts as o')->join('students as s','s.id','=','o.student_id')->where('o.academic_period_id',$p->id)->select('o.*','s.last_name','s.first_name')->orderByDesc('o.id')->get();$stays=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->where('st.status','active')->select('st.id','st.student_id','s.last_name','s.first_name')->get();return view('dormitory.orders',compact('rows','stays'));}
public function store(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['dormitory_stay_id'=>'required|exists:dormitory_stays,id','type'=>'required|in:checkin,transfer,checkout','order_on'=>'required|date','basis'=>'nullable|string|max:3000']);$st=DB::table('dormitory_stays')->find($d['dormitory_stay_id']);$seq=(DB::table('dormitory_order_drafts')->max('id')??0)+1;$num=sprintf('ОБЩ-%s-%04d',date('Y'),$seq);$snap=$this->snapshot($st);$id=DB::table('dormitory_order_drafts')->insertGetId(['academic_period_id'=>$p->id,'student_id'=>$st->student_id,'dormitory_stay_id'=>$st->id,'type'=>$d['type'],'number'=>$num,'order_on'=>$d['order_on'],'basis'=>$d['basis']??null,'snapshot_json'=>json_encode($snap,JSON_UNESCAPED_UNICODE),'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('dormitory.order.print',$id);}
public function print(Request $r,$id){$this->manage($r);$o=DB::table('dormitory_order_drafts')->find($id);abort_if(!$o,404);$data=json_decode($o->snapshot_json,true);return view('dormitory.order-print',compact('o','data'));}
private function snapshot($st){$s=DB::table('students')->find($st->student_id);$place=DB::table('dormitory_places as p')->join('dormitory_rooms as rm','rm.id','=','p.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->where('p.id',$st->dormitory_place_id)->select('p.number place','rm.number room','b.name building','b.address')->first();return ['student'=>$s,'stay'=>$st,'place'=>$place,'organization'=>DB::table('organization_settings')->first()];}}
